// Fisher-Yates shuffle in place
function shuffleArray(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}

// توزيع متوازن: لـ count سؤال على optionCount خيار،
// كل خيار يحصل على floor(count/optionCount) أو +1 إجابة صحيحة بشكل عشوائي
function balancedPositions(count, optionCount) {
    const base = Math.floor(count / optionCount);
    const extra = count - base * optionCount;
    // اختيار عشوائي لأي مواضع تحصل على +1 إجابة
    const indices = shuffleArray(Array.from({ length: optionCount }, (_, i) => i));
    const extraSet = new Set(indices.slice(0, extra));
    const positions = [];
    for (let i = 0; i < optionCount; i++) {
        const reps = base + (extraSet.has(i) ? 1 : 0);
        for (let j = 0; j < reps; j++) positions.push(i);
    }
    return shuffleArray(positions);
}

// مولّد أسئلة مبني على بيانات learn الفعلية للأداة + توزيع متوازن لمواضع الإجابة الصحيحة
function generateToolQuestions(tool) {
    const l = tool.learn;
    const name = tool.name;
    const wrongPool = [
        'يعتمد كلياً على الحدس الشخصي ويتجاهل البيانات والتحليل الموضوعي',
        'يضيف طبقات معقّدة من الإجراءات البيروقراطية دون قيمة عملية حقيقية',
        'يقطع قنوات التواصل بين الأقسام ويعزل كل فريق على حدة',
        'يركّز على كمية المخرجات السريعة على حساب جودتها وأثرها الفعلي',
        'يقلّل من المساءلة ويترك النتائج دون قياس أو متابعة منتظمة',
        'يحصر كل سلطة اتخاذ القرار في شخص واحد دون تفويض أو مشاركة',
        'يؤجّل القرارات الحاسمة لأجل غير مسمّى انتظاراً لظروف مثالية',
        'يتجنّب الاستثمار في تدريب الفريق ويعتمد على المهارات الحالية فقط',
        'يلغي التقييم المستمرّ للأداء ويكتفي بمراجعة سنوية واحدة شاملة',
        'يفرض نظاماً صارماً جامداً دون أيّ مرونة أو مراجعة دورية للتحسين',
        'يستجيب متأخراً لتغيّرات السوق بعد أن يفوت أوان المعالجة المناسبة',
        'يخفي المعلومات الحرجة عن الفريق ويشاركها فقط عند وقوع الأزمات',
        'يستبعد الإدارة العليا من القرار ويتجاوز التسلسل الإداري المعتمد',
        'يطبّق حلولاً جاهزة منسوخة دون فهم جذور المشكلة وسياقها الخاصّ',
        'يعتمد على تقنية واحدة في كل المواقف دون مراعاة اختلاف الحالات'
    ];
    const pickWrong = (n, excludeArr = []) => {
        const filtered = wrongPool.filter(w => !excludeArr.includes(w));
        return shuffleArray([...filtered]).slice(0, n);
    };
    const baseQs = [
        { q: `ما هو ${name} باختصار؟`, correctAnswer: l.intro, explanation: l.intro },
        { q: `كم عدد المكونات/المفاهيم الأساسية في ${name}؟`,
          correctAnswer: `${l.points.length} مكونات/مفاهيم`,
          fixedWrongs: ['2 مكونان فقط', '6 مكونات', '8 مكونات أو أكثر'],
          explanation: `${name} يحتوي على ${l.points.length} مكونات أساسية: ${l.points.join(' • ')}` },
        { q: `أي مما يلي يُعتبر من المكونات الأساسية لـ ${name}؟`,
          correctAnswer: l.points[0],
          explanation: `المكونات الأساسية: ${l.points.join(' • ')}` },
        { q: `متى يكون استخدام ${name} الأكثر فائدة؟`, correctAnswer: l.useCase, explanation: l.useCase },
        { q: `أي من الفوائد الرئيسية لـ ${name}؟`, correctAnswer: l.benefits[0], explanation: `الفوائد: ${l.benefits.join(' • ')}` },
        { q: `أي مما يلي يُعدّ ميزة تنافسية لـ ${name}؟`,
          correctAnswer: l.benefits[1] || l.benefits[0],
          explanation: `الفوائد: ${l.benefits.join(' • ')}` },
        { q: `أي مثال واقعي على تطبيق ناجح لـ ${name}؟`, correctAnswer: l.example, explanation: l.example },
        { q: `ما أكبر تحدٍ شائع عند تطبيق ${name}؟`, correctAnswer: l.pitfall, explanation: l.pitfall },
        { q: `ما الذي يجب الحذر منه عند العمل بـ ${name}؟`, correctAnswer: l.pitfall, explanation: l.pitfall },
        { q: `أي مكوّن إضافي يُميّز ${name} عن البدائل التقليدية؟`,
          correctAnswer: l.points[l.points.length - 1],
          explanation: `أبرز مكونات ${name}: ${l.points.join(' • ')}` }
    ];
    // توزيع متوازن: 10 أسئلة × 4 خيارات → 2 أو 3 لكل من أ ب ج د
    const targetPositions = balancedPositions(baseQs.length, 4);
    return baseQs.map((item, qIdx) => {
        const options = item.fixedWrongs
            ? [item.correctAnswer, ...item.fixedWrongs]
            : [item.correctAnswer, ...pickWrong(3, [item.correctAnswer])];
        // الإجابة الصحيحة دائماً في options[0]، ننقلها للموضع المستهدف
        const targetPos = targetPositions[qIdx];
        const finalOptions = [...options];
        if (targetPos !== 0) {
            [finalOptions[0], finalOptions[targetPos]] = [finalOptions[targetPos], finalOptions[0]];
        }
        return {
            q: item.q,
            options: finalOptions,
            correct: targetPos,
            explanation: item.explanation
        };
    });
}

